// WONDERLAND — A COMPANION'S FIGURE, AS DATA.
//
// WHY A TEXT FILE AND NOT AN ASSET. The two companion embodiments are a development preview, and the
// asset lane -- Content/, the Blender forge -- belongs to the world build. So a figure is a list of boxes
// in a small line format under wonderland/Companions/, generated by wonderland/Tools/companion_figures.py
// and read when the companion spawns. No .uasset is created, nothing in Content changes, and the look can
// be retuned and reloaded in PIE (`wl.Companion.Reload`) without a compile. When a design is approved it
// can become a real mesh in the forge; the runtime does not care where its boxes came from.
//
// THE FORMAT, one record per line, `#` to end of line is a comment:
//
//   wlvox 1
//   voxel <uu per grid unit>
//   material <name> <lit|rim|glow|add> <r> <g> <b> [strength]
//   part <name> <parent|-> <pivot x y z> <motion> [a] [b]
//   box <part> <material> <centre x y z> <size x y z> [pitch yaw roll]
//
// Grid axes are Unreal's: +X forward (where the face looks), +Y right, +Z up. The origin is the point
// that floats at hover height. Colours are linear. Parts are declared parent-first. Motions:
// none, float, head, wing <side>, tail <index> <count>, orbit <degrees per second>, blink, twinkle <phase>,
// stride <phase> <lift>, knee <phase> <bend>, spine <amount> <phase>, trail <index> <count>.
//
// PURE, AND ALL OR NOTHING. No engine state is touched here. A figure that fails to parse names the line
// and the reason and is never returned half-built, so a typo in a figure file can never spawn a companion
// missing its head.
//
// PLAIN TYPES ON PURPOSE. Nothing below is reflected: these records never cross to Relay, never reach a
// Blueprint and never serialise, so they stay out of the C++ ↔ TypeScript parity table entirely.
#pragma once

#include "CoreMinimal.h"

enum class EWonderlandCompanionMaterialKind : uint8
{
	/** Opaque and lit: ivory shell, gold, the dark visor. */
	Lit,
	/** Lit, with a fresnel rim of its own colour. */
	Rim,
	/** Opaque and unlit, brighter than 1 where it should bloom: eyes, crystal cores, wisp cores. */
	Glow,
	/** Additive: soft halos. Nearly invisible over daylight, so never the only thing making a silhouette. */
	Additive
};

enum class EWonderlandCompanionMotion : uint8
{
	None,
	/** The whole figure's slow hover. */
	Float,
	/** A gentle tilt. */
	Head,
	/** A flap about the wing root. A = side, -1 left, +1 right. */
	Wing,
	/** One segment of the spectral tail. A = index from the body, B = segment count. */
	Tail,
	/** A slow yaw about the part's pivot. A = degrees per second. */
	Orbit,
	/** Eyes: an occasional squash to a line. */
	Blink,
	/** Sparkles: a breathing scale. A = phase, 0..1. */
	Twinkle,
	/**
	 * A LIMB'S UPPER JOINT, walking. A = this leg's phase in the gait cycle, 0..1 (diagonal pairs are half a cycle
	 * apart); B = how far the foot lifts on the swing, as a multiple of the default.
	 *
	 * Driven by the body's measured ground speed, so a creature standing still does not march on the spot.
	 */
	Stride,
	/**
	 * THE JOINT BELOW A STRIDE, bending through the swing and straightening under load. A = the same phase as its
	 * hip; B = how far it bends.
	 *
	 * IT LAGS ITS HIP ON PURPOSE. A knee that bends on the same frame as the hip above it is the most mechanical
	 * thing a walk can do; the delay is what makes a leg read as a leg rather than as a hinge.
	 */
	Knee,
	/**
	 * THE BODY, FLEXING WITH THE GAIT: rolling into the stride, yawing against it, and bobbing twice a cycle.
	 * A = how much, as a multiple of the default; B = a phase offset.
	 */
	Spine,
	/**
	 * A SEGMENT THAT STREAMS AND WHIPS rather than swinging in place. A = index along the chain, B = chain length.
	 *
	 * Unlike Tail, its amplitude rises with the body's speed and it sweeps backward as the body moves, so a tail
	 * trails behind a running creature and settles when it stops.
	 */
	Trail,
	/**
	 * LIVING SHADOW (Shadow Flame, founder 2026-10-01). Never drawn as boxes: the part's boxes only bound where its black
	 * tendrils are born, and AWonderlandCompanionEmbodiment::RebuildShadows lays the tendrils every frame.
	 * A = how many tendrils grow here; B = how long they reach, in figure units.
	 *
	 * A plain enum value, deliberately: this enum is not reflected, so adding to it adds no early FName (the UE 5.8
	 * Niagara name-table crash a new reflected name once caused at boot).
	 */
	Shadow
};

struct FWonderlandCompanionMaterial
{
	FName Name;
	EWonderlandCompanionMaterialKind Kind = EWonderlandCompanionMaterialKind::Lit;
	FLinearColor Color = FLinearColor::White;
	float Strength = 1.0f;
	/**
	 * OPTIONAL: which player colour this surface follows, declared by the figure after the strength --
	 * `material heart glow 0.95 0.08 0.02 9.000 secondary`. "secondary" takes the mascot SECONDARY colour at the
	 * authored brightness; "secondary_light" the same colour lifted toward white (a flame's pale core);
	 * "secondary_deep" a deep shade of it for a lit cloth (Jack Flame's suit, WonderlandMascotStyle::DeepAccentColour). Empty
	 * means the material is routed by its name, as every material was before (WonderlandMascotStyle::ChannelFor).
	 * Older engines stop reading the line at the strength, so a tagged figure still loads everywhere.
	 */
	FName Channel;
};

struct FWonderlandCompanionPart
{
	FName Name;
	/** Index into Parts, always lower than this part's own index. INDEX_NONE for the root. */
	int32 Parent = INDEX_NONE;
	/** Figure space, grid units. */
	FVector Pivot = FVector::ZeroVector;
	EWonderlandCompanionMotion Motion = EWonderlandCompanionMotion::None;
	float A = 0.0f;
	float B = 0.0f;
};

struct FWonderlandCompanionBox
{
	int32 Part = 0;
	int32 Material = 0;
	/** Figure space, grid units. */
	FVector Centre = FVector::ZeroVector;
	FVector Size = FVector::OneVector;
	FRotator Rotation = FRotator::ZeroRotator;
};

struct WONDERLAND_API FWonderlandCompanionFigure
{
	/** Unreal units per grid unit. */
	float VoxelUU = 2.5f;
	/**
	 * THE CANONICAL BODY'S VERTICAL EXTENT, grid units: the `body <lowest> <highest>` record the generator writes from its
	 * base Relay Dog -- the dog under the costume, never its horns, crown or fire. Every mascot skin is sized so this body
	 * stands exactly Relay OG's height (founder, 2026-09-30, a HARD rule: "ALL mascot skins must be the same overall height as the canonical Relay OG mascot skin"). A figure without the record is not normalized.
	 */
	float BodyLowest = 0.0f;
	float BodyHighest = 0.0f;
	bool HasBody() const { return BodyHighest - BodyLowest > 0.1f; }
	TArray<FWonderlandCompanionMaterial> Materials;
	TArray<FWonderlandCompanionPart> Parts;
	TArray<FWonderlandCompanionBox> Boxes;

	/**
	 * Hard ceilings, so a runaway generator cannot put ten thousand components into a world.
	 *
	 * RAISED FOR THE PROJECT AVATARS. Boxes are ISM instances, one component per material, so forty thousand of
	 * them is forty thousand instances across a dozen draw calls -- not forty thousand components. The founder
	 * rejected the avatars as LEGO, and the cause is resolution: a 5.6 m creature built at 8-12 uu voxels is a
	 * stack of bricks, while the companions the founder named as the bar are built at 2.5 uu. Fine voxels on a
	 * body that size need this ceiling, and a runaway generator is still stopped, just later.
	 */
	static constexpr int32 MaxBoxes = 40000;
	static constexpr int32 MaxParts = 48;
	// 14, not 12: every mascot skin now carries its eye halo as its own additive material, and Arden Infernal,
	// Apollo and Hagoromo were already at the old cap. The generator asserts the same number.
	static constexpr int32 MaxMaterials = 14;

	/**
	 * Parse a whole figure. On failure returns false, leaves OutFigure empty and names the line in
	 * OutError. On success the figure has at least one part and one box, and every index is valid.
	 */
	static bool Parse(const FString& Text, FWonderlandCompanionFigure& OutFigure, FString& OutError);

	int32 FindPart(FName Name) const;
	int32 FindMaterial(FName Name) const;
};
